create table if not exists public.booking_manage_tokens(id uuid primary key default gen_random_uuid(),booking_id uuid not null references public.bookings(id) on delete cascade,business_id uuid not null references public.businesses(id) on delete cascade,token_hash text not null unique,created_at timestamptz not null default now(),expires_at timestamptz,revoked_at timestamptz,last_used_at timestamptz,created_by uuid references auth.users(id),source text not null default 'system');
create unique index if not exists booking_manage_tokens_one_active on public.booking_manage_tokens(booking_id) where revoked_at is null;
create table if not exists public.booking_change_audit(id uuid primary key default gen_random_uuid(),booking_id uuid not null references public.bookings(id) on delete cascade,business_id uuid not null references public.businesses(id) on delete cascade,change_source text not null check(change_source in('customer','staff','system')),change_type text not null,old_values jsonb not null default '{}'::jsonb,new_values jsonb not null default '{}'::jsonb,resulting_total_cents integer,resulting_balance_due_cents integer,payment_reference text,created_at timestamptz not null default now());
create index if not exists booking_change_audit_booking_idx on public.booking_change_audit(booking_id,created_at desc);
alter table public.booking_manage_tokens enable row level security; alter table public.booking_change_audit enable row level security;
create policy "staff manage booking tokens" on public.booking_manage_tokens for all to authenticated using(public.has_business_role(business_id,array['owner','admin','manager'])) with check(public.has_business_role(business_id,array['owner','admin','manager']));
create policy "staff view booking audit" on public.booking_change_audit for select to authenticated using(public.has_business_role(business_id,array['owner','admin','manager']));
